        introContainer.Size = UDim2.new(0, introTotalWidth, 0, 92)
        introContainer.Position = UDim2.new(0.5, -introTotalWidth / 2, 0.5, -46)
        for i, char in ipairs(introTitle) do
            local letter = Instance.new("TextLabel")
