            letter.Position = UDim2.new(0, (i - 1) * (introLetterWidth + introLetterGap), 0, 8)
            -- Letter tiles mirror the dark rounded controls in asset 134356955255674.
            letter.BackgroundColor3 = Color3.fromRGB(10, 12, 18)
            letter.BackgroundTransparency = 1
            letter.BorderSizePixel = 0
            letter.Text = char
            letter.TextColor3 = Color3.fromRGB(225, 229, 236)
            letter.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            letter.TextStrokeTransparency = 0.35
            letter.TextSize = 42
            letter.Font = Enum.Font.GothamBlack
            letter.TextScaled = false
            letter.TextTransparency = 1
            letter.Rotation = (i % 2 == 0) and 8 or -8
            -- No tile, panel, or box behind the intro letters.
