                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(205, 214, 226)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
            })
            letterGradient.Rotation = 90
            letterGradient.Parent = letter
            table.insert(introLetters, {label = letter, stroke = letterStroke})
        end
    
        local introSkipped = false
    
        -- Clean music-synced reveal: each letter appears on a fixed beat.
        -- The animation follows Sound.TimePosition, so it stays aligned even if loading takes time.
        task.spawn(function()
            local revealed = 0
            local lastPulseBeat = -1
            local revealStart = 0.20
            local beatLength = 0.32
            while not introSkipped and introGui.Parent do
                local musicTime = introSound and introSound.IsPlaying and math.max(introSound.TimePosition, 0) or 0
                local targetRevealed = math.clamp(math.floor((musicTime - revealStart) / beatLength) + 1, 0, #introLetters)
                while revealed < targetRevealed do
                    revealed += 1
                    local item = introLetters[revealed]
                    local letter = item and item.label
                    local stroke = item and item.stroke
                    if letter then
                        local finalX = (revealed - 1) * (introLetterWidth + introLetterGap)
                        local revealTween = TweenService:Create(letter, TweenInfo.new(0.34, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                            TextTransparency = 0,
                            TextStrokeTransparency = 0.35,
                            BackgroundTransparency = 1,
                            Position = UDim2.new(0, finalX, 0, 8),
                            Rotation = 0,
                        })
                        revealTween:Play()
                    end
                end
    
                local currentBeat = math.floor(math.max(musicTime, 0) / beatLength)
                if currentBeat ~= lastPulseBeat then
                    lastPulseBeat = currentBeat
                    introScale.Scale = 1.025
                    TweenService:Create(introScale, TweenInfo.new(0.16, Enum.EasingStyle.Linear), {
                        Scale = 1,
                    }):Play()
                end
                task.wait(0.03)
