    -- ===================== MIRROR TP DOWN =====================
    local mirrorTPDownEnabled = true
    local mirrorTPPreviousY = {}
    local mirrorTPLastTime = 0
    
    -- Dedicated Mirror TP Down persistence. This is intentionally separate from the
    -- main config so older config writers cannot overwrite the Mirror TP Down state.
    local MIRROR_TP_CONFIG_FILE = "AmiriDuels_MirrorTPDown.json"
    local function saveMirrorTPDownConfig()
        refreshFileApis()
        if not canSaveConfig or type(_ace_writefile) ~= "function" then return false end
        local payload = { enabled = (mirrorTPDownEnabled == true), savedAt = os.time(), version = 1 }
        local ok, json = pcall(function() return HS:JSONEncode(payload) end)
        if not ok or type(json) ~= "string" then return false end
        local wok = pcall(_ace_writefile, MIRROR_TP_CONFIG_FILE, json)
        if not wok then return false end
        local rok, check = pcall(_ace_readfile, MIRROR_TP_CONFIG_FILE)
        if not rok or check ~= json then return false end
        return true
    end
    local function loadMirrorTPDownConfig()
        refreshFileApis()
        if not canSaveConfig or type(_ace_readfile) ~= "function" then return nil end
        if type(_ace_isfile) == "function" and not _ace_isfile(MIRROR_TP_CONFIG_FILE) then return nil end
        local ok, raw = pcall(_ace_readfile, MIRROR_TP_CONFIG_FILE)
        if not ok or type(raw) ~= "string" then return nil end
        local dok, data = pcall(function() return HS:JSONDecode(raw) end)
        if not dok or type(data) ~= "table" or type(data.enabled) ~= "boolean" then return nil end
        return data.enabled
    end
    
    local MIRROR_TP_COOLDOWN = 0.08
    local DROP_THRESHOLD = 3
    
    -- Always place Mirror TP Down on the actual ground below the local player.
    -- This prevents the old fixed Y (-7) from sending the player underground.
    local function getMirrorTPGroundY(myRoot, myChar)
        if not myRoot then return nil end
    
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local exclude = {}
        if myChar then table.insert(exclude, myChar) end
    
        -- Ignore player characters so the ray reaches the map/platform below.
        for _, p in ipairs(Players:GetPlayers()) do
            if p.Character and p.Character ~= myChar then
                table.insert(exclude, p.Character)
            end
        end
        params.FilterDescendantsInstances = exclude
        params.IgnoreWater = false
    
        local pos = myRoot.Position
    
        -- Start only a little above the player so we cannot accidentally hit
        -- an overhead platform first. Search downward for the nearest surface.
        local origin = Vector3.new(pos.X, pos.Y + 5, pos.Z)
        local direction = Vector3.new(0, -500, 0)
        local hit = workspace:Raycast(origin, direction, params)
    
        if hit then
            -- Keep the whole HumanoidRootPart clearly above the ground.
            -- Use the root half-height plus a small safety gap so it cannot
            -- spawn inside/slightly below thin floors.
            local rootHalfHeight = math.max(myRoot.Size.Y * 0.5, 1)
            return hit.Position.Y + rootHalfHeight + 0.35
        end
    
        return nil
    end
    
    local function setMirrorTPDown(on)
        mirrorTPDownEnabled = (on == true)
        if not mirrorTPDownEnabled then
            table.clear(mirrorTPPreviousY)
        end
    end
    
    RunService.Heartbeat:Connect(function()
        if not mirrorTPDownEnabled then
            table.clear(mirrorTPPreviousY)
            return
        end
    
        -- autoBatEnabled covers both NORMAL and BYPASS modes in this script.
        local aimbotActive = (autoBatEnabled == true)
        if not aimbotActive then
            table.clear(mirrorTPPreviousY)
            return
        end
    
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr == LP then
                continue
            end
    
            local char = plr.Character
            if not char then
                continue
            end
    
            local root = char:FindFirstChild("HumanoidRootPart")
            if not root then
                continue
            end
    
            local currentY = root.Position.Y
            local previousY = mirrorTPPreviousY[plr.UserId]
    
            if previousY and (previousY - currentY) >= DROP_THRESHOLD then
                local myChar = LP.Character
                if myChar then
                    local myRoot = myChar:FindFirstChild("HumanoidRootPart")
                    local myHum = myChar:FindFirstChildOfClass("Humanoid")
    
                    if myRoot and myHum and myHum.Health > 0 then
                        local now = tick()
                        if now - mirrorTPLastTime >= MIRROR_TP_COOLDOWN then
                            mirrorTPLastTime = now
    
                            local offsetX = (math.random() - 0.5) * 0.4
                            local offsetZ = (math.random() - 0.5) * 0.4
                            local groundY = getMirrorTPGroundY(myRoot, myChar)
    
                            -- Only TP when an actual surface was found.
                            if groundY then
                                myRoot.CFrame = CFrame.new(
                                    myRoot.Position.X + offsetX,
                                    groundY,
                                    myRoot.Position.Z + offsetZ
                                )
    
                                myRoot.AssemblyLinearVelocity =
                                    Vector3.new(offsetX * 0.5, 0, offsetZ * 0.5)
                            end
    
                        end
                    end
                end
    
                table.clear(mirrorTPPreviousY)
                break
            end
    
            mirrorTPPreviousY[plr.UserId] = currentY
        end
    end)
    -- =================== END MIRROR TP DOWN ===================
    
    local defLightBrightness = nil; local defLightClock = nil; local defLightAmbient = nil; local defGlobalShadows = nil; local defFogEnd = nil
    function applyAntiLagDerender(obj)
        pcall(function()
            if obj:IsA("Accessory") or obj:IsA("Hat") then obj:Destroy()
            elseif obj:IsA("BasePart") then obj.Material = Enum.Material.Plastic; obj.Reflectance = 0; obj.CastShadow = false
            elseif obj:IsA("Decal") or obj:IsA("Texture") then obj.Transparency = 1
            elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") or obj:IsA("Fire") or obj:IsA("Smoke") or obj:IsA("Sparkles") then obj.Enabled = false
            elseif obj:IsA("AnimationController") or obj:IsA("Animator") then
                for _, t in ipairs(obj:GetPlayingAnimationTracks()) do pcall(function() t:Stop(0) end) end
            end
        end)
    end
    function enableAntiLag()
        removeAccessoriesEnabled = true; antiLagEnabled = true; _G.Lust.Active.antiLag = true
        if defLightBrightness == nil then
            defLightBrightness = Lighting.Brightness; defLightClock = Lighting.ClockTime
            defLightAmbient = Lighting.OutdoorAmbient; defGlobalShadows = Lighting.GlobalShadows; defFogEnd = Lighting.FogEnd
        end
        Lighting.GlobalShadows = false; Lighting.FogEnd = 1e10; Lighting.Brightness = 0
        for _, e in pairs(Lighting:GetChildren()) do
            pcall(function()
                if e:IsA("BlurEffect") or e:IsA("SunRaysEffect") or e:IsA("ColorCorrectionEffect") or e:IsA("BloomEffect") or e:IsA("DepthOfFieldEffect") then e.Enabled = false end
            end)
        end
        for _, obj in ipairs(workspace:GetDescendants()) do applyAntiLagDerender(obj) end
        if _G.Lust.Connections.antiLagDesc then _G.Lust.Connections.antiLagDesc:Disconnect() end
        _G.Lust.Connections.antiLagDesc = workspace.DescendantAdded:Connect(function(obj)
            if removeAccessoriesEnabled then applyAntiLagDerender(obj) end
        end)
        if setAntiLagVisual then setAntiLagVisual(true) end
    end
    function disableAntiLag()
        removeAccessoriesEnabled = false; antiLagEnabled = false; _G.Lust.Active.antiLag = false
        if _G.Lust.Connections.antiLagDesc then _G.Lust.Connections.antiLagDesc:Disconnect(); _G.Lust.Connections.antiLagDesc = nil end
        if defLightBrightness ~= nil then Lighting.Brightness = defLightBrightness end
        if defLightClock ~= nil then Lighting.ClockTime = defLightClock end
        if defLightAmbient ~= nil then Lighting.OutdoorAmbient = defLightAmbient end
        if defGlobalShadows ~= nil then Lighting.GlobalShadows = defGlobalShadows end
        if defFogEnd ~= nil then Lighting.FogEnd = defFogEnd end
        for _, e in pairs(Lighting:GetChildren()) do
            pcall(function()
                if e:IsA("BlurEffect") or e:IsA("SunRaysEffect") or e:IsA("ColorCorrectionEffect") or e:IsA("BloomEffect") or e:IsA("DepthOfFieldEffect") then e.Enabled = true end
            end)
        end
        if setAntiLagVisual then setAntiLagVisual(false) end
    end
    local function stopAntiDie()
        if _antiDieConn then
            _antiDieConn:Disconnect()
            _antiDieConn = nil
        end
        if _antiDieHealthConn then
            _antiDieHealthConn:Disconnect()
            _antiDieHealthConn = nil
        end
        if _antiDieStateConn then
            _antiDieStateConn:Disconnect()
            _antiDieStateConn = nil
        end
    end
    
    local function setupAntiDie(char)
        stopAntiDie()
        if not char or not antiDieEnabled or _isResetting then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then
            hum = char:WaitForChild("Humanoid", 5)
            if not hum then return end
        end
        pcall(function()
            hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
        end)
        _antiDieHealthConn = hum:GetPropertyChangedSignal("Health"):Connect(function()
            if antiDieEnabled and not _isResetting and hum.Parent and hum.Health < hum.MaxHealth then
                pcall(function()
                    hum.Health = hum.MaxHealth
                end)
            end
        end)
        _antiDieConn = RunService.Heartbeat:Connect(function()
            if antiDieEnabled and not _isResetting and hum and hum.Parent then
                pcall(function()
                    if hum.Health < hum.MaxHealth then
                        hum.Health = hum.MaxHealth
                    end
                end)
            end
        end)
        _antiDieStateConn = hum.StateChanged:Connect(function(_, newState)
            if antiDieEnabled and not _isResetting and newState == Enum.HumanoidStateType.Dead then
                pcall(function()
                    hum.Health = hum.MaxHealth
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
            end
        end)
    end
    
    function enableAntiDie()
        antiDieEnabled = true
        _G.Lust.Active.antiDie = true
        setupAntiDie(LP.Character)
    end
    
    function disableAntiDie()
        antiDieEnabled = false
        _G.Lust.Active.antiDie = false
        stopAntiDie()
    end
    
    -- ============================================================
    -- RAINBOW JOYSTICK
    -- Recolors only Roblox mobile thumbstick UI elements.
    -- ============================================================
    local rainbowJoystickOriginals = {}
    local rainbowJoystickLastScan = 0
    
    local function isRainbowJoystickObject(obj)
        if not obj then return false end
        local n = string.lower(tostring(obj.Name or ""))
        if n:find("thumbstick", 1, true) then return true end
        if n:find("dynamicthumbstick", 1, true) then return true end
        return false
    end
    
    local function rainbowJoystickScanAndColor(hue)
        local roots = {}
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        if pg then
            local touchGui = pg:FindFirstChild("TouchGui")
            if touchGui then table.insert(roots, touchGui) end
            local dynamic = pg:FindFirstChild("DynamicThumbstickFrame", true)
            if dynamic and not touchGui then table.insert(roots, dynamic) end
        end
        local cg = game:GetService("CoreGui")
        if cg then
            local robloxGui = cg:FindFirstChild("RobloxGui")
            if robloxGui then
                local touch = robloxGui:FindFirstChild("TouchControlFrame", true)
                if touch then table.insert(roots, touch) end
                local dynamic = robloxGui:FindFirstChild("DynamicThumbstickFrame", true)
                if dynamic and not touch then table.insert(roots, dynamic) end
            end
        end
    
        local seen = {}
        for _, root in ipairs(roots) do
            if isRainbowJoystickObject(root) then
                if not seen[root] then
                    seen[root] = true
                    local obj = root
                    if rainbowJoystickOriginals[obj] == nil then
                        local saved = {}
                        pcall(function()
                            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then saved.imageColor3 = obj.ImageColor3 end
                            if obj:IsA("Frame") or obj:IsA("ImageLabel") or obj:IsA("ImageButton") then saved.backgroundColor3 = obj.BackgroundColor3 end
                        end)
                        rainbowJoystickOriginals[obj] = saved
                    end
                    local c = Color3.fromHSV((hue + (#obj.Name % 17) * 0.012) % 1, 1, 1)
                    pcall(function()
                        if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then obj.ImageColor3 = c end
                        if obj:IsA("Frame") then obj.BackgroundColor3 = c end
                    end)
                end
            end
            for _, obj in ipairs(root:GetDescendants()) do
                if isRainbowJoystickObject(obj) and not seen[obj] then
                    seen[obj] = true
                    if rainbowJoystickOriginals[obj] == nil then
                        local saved = {}
                        pcall(function()
                            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                                saved.imageColor3 = obj.ImageColor3
                            end
                            if obj:IsA("Frame") or obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                                saved.backgroundColor3 = obj.BackgroundColor3
                            end
                        end)
                        rainbowJoystickOriginals[obj] = saved
                    end
                    local c = Color3.fromHSV((hue + (#obj.Name % 17) * 0.012) % 1, 1, 1)
                    pcall(function()
                        if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                            obj.ImageColor3 = c
                        end
                        if obj:IsA("Frame") then
                            obj.BackgroundColor3 = c
                        end
                    end)
                end
            end
        end
    end
    
    local function restoreRainbowJoystick()
        for obj, saved in pairs(rainbowJoystickOriginals) do
            if obj and obj.Parent and saved then
                pcall(function()
                    if saved.imageColor3 and (obj:IsA("ImageLabel") or obj:IsA("ImageButton")) then
                        obj.ImageColor3 = saved.imageColor3
                    end
                    if saved.backgroundColor3 and obj:IsA("Frame") then
                        obj.BackgroundColor3 = saved.backgroundColor3
                    end
                end)
            end
        end
        table.clear(rainbowJoystickOriginals)
    end
    
    function enableRainbowJoystick()
        rainbowJoystickEnabled = true
        _G.Lust.Active.rainbowJoystick = true
        if _G.Lust.Connections.rainbowJoystick then return end
        rainbowJoystickLastScan = 0
        _G.Lust.Connections.rainbowJoystick = RunService.RenderStepped:Connect(function()
            if not rainbowJoystickEnabled then
                restoreRainbowJoystick()
                local c = _G.Lust.Connections.rainbowJoystick
                if c then pcall(function() c:Disconnect() end) end
                _G.Lust.Connections.rainbowJoystick = nil
                return
            end
            local now = os.clock()
            if now - rainbowJoystickLastScan >= 0.08 then
                rainbowJoystickLastScan = now
                rainbowJoystickScanAndColor((now * 0.22) % 1)
            end
        end)
    end
    
    function disableRainbowJoystick()
        rainbowJoystickEnabled = false
        _G.Lust.Active.rainbowJoystick = false
        local c = _G.Lust.Connections.rainbowJoystick
        if c then pcall(function() c:Disconnect() end) end
        _G.Lust.Connections.rainbowJoystick = nil
        restoreRainbowJoystick()
    end
    
    LP.CharacterAdded:Connect(function(char)
        task.wait(0.15)
        if antiDieEnabled and not _isResetting then
            setupAntiDie(char)
        end
    end)
    
    function applyStretchFOV(val) local cam = workspace.CurrentCamera; if cam then pcall(function() cam.FieldOfView = val end) end end
    function enableStretch()
        if _G.Lust.Connections.stretch then return end
        _G.Lust.Active.stretch = true; stretchEnabled = true
        local cam = workspace.CurrentCamera; if not cam then return end
        origFOV = cam.FieldOfView or 70
        applyStretchFOV(120)
        _G.Lust.Connections.stretch = RunService.RenderStepped:Connect(function()
            if not stretchEnabled then _G.Lust.Connections.stretch:Disconnect(); _G.Lust.Connections.stretch = nil; return end
            local c = workspace.CurrentCamera
            if c then c.CFrame = c.CFrame * CFrame.new(0,0,0,1,0,0,0,0.7,0,0,0,1) end
        end)
        if _G.Lust.Connections.stretchFov then _G.Lust.Connections.stretchFov:Disconnect() end
        _G.Lust.Connections.stretchFov = RunService.RenderStepped:Connect(function()
            if stretchEnabled then applyStretchFOV(120)
            else _G.Lust.Connections.stretchFov:Disconnect(); _G.Lust.Connections.stretchFov = nil end
        end)
        if _G.stretchToggleSetter then _G.stretchToggleSetter(true) end
    end
    function disableStretch()
        _G.Lust.Active.stretch = false; stretchEnabled = false
        if _G.Lust.Connections.stretch then _G.Lust.Connections.stretch:Disconnect(); _G.Lust.Connections.stretch = nil end
        if _G.Lust.Connections.stretchFov then _G.Lust.Connections.stretchFov:Disconnect(); _G.Lust.Connections.stretchFov = nil end
        local cam = workspace.CurrentCamera; if cam then pcall(function() cam.FieldOfView = povEnabled and 120 or (origFOV or 70) end) end
        if _G.stretchToggleSetter then _G.stretchToggleSetter(false) end
    end
    function enablePOV()
        povEnabled = true
        local cam = workspace.CurrentCamera
        if not cam then return end
        pcall(function() cam.FieldOfView = 120 end)
        if _G.Lust.Connections.povFov then
            _G.Lust.Connections.povFov:Disconnect()
            _G.Lust.Connections.povFov = nil
        end
        _G.Lust.Connections.povFov = RunService.RenderStepped:Connect(function()
            if not povEnabled then
                if _G.Lust.Connections.povFov then
                    _G.Lust.Connections.povFov:Disconnect()
                    _G.Lust.Connections.povFov = nil
                end
                return
            end
            local c = workspace.CurrentCamera
            if c then pcall(function() c.FieldOfView = 120 end) end
        end)
    end
    
    function disablePOV()
        povEnabled = false
        if _G.Lust.Connections.povFov then
            _G.Lust.Connections.povFov:Disconnect()
            _G.Lust.Connections.povFov = nil
        end
        local cam = workspace.CurrentCamera
        if cam then
            pcall(function()
                if stretchEnabled then
                    cam.FieldOfView = 120
                else
                    cam.FieldOfView = origFOV or 70
                end
            end)
        end
    end
    local _mainGuiSaveToken = 0
    local function persistMainGuiPosition(reason)
        if not main or not main.Parent then return false end
        if _isBuildingGui or _isLoading or _isResetting then return false end
        savedMainGuiPos = {
            XScale = main.Position.X.Scale, XOffset = main.Position.X.Offset,
            YScale = main.Position.Y.Scale, YOffset = main.Position.Y.Offset
        }
        _mainGuiSaveToken = _mainGuiSaveToken + 1
        local token = _mainGuiSaveToken
        task.defer(function()
            if token ~= _mainGuiSaveToken then return end
            if _isBuildingGui or _isLoading or _isResetting then return end
            pcall(syncFloatingButtonPositions)
            pcall(function() saveAllSettings() end)
        end)
        return true
    end
    
    local function drag(f)
        local dn, ds, sp, di = false
        f.InputBegan:Connect(function(i)
            if uiLocked then return end
            if _isDraggingButton then return end
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                dn = true; ds = i.Position; sp = f.Position
                i.Changed:Connect(function()
                    if i.UserInputState == Enum.UserInputState.End then
                        dn = false
                        if (f == main or f.Name == "MenuDragHandle") then
                            persistMainGuiPosition("menu drag release")
                        end
                    end
                end)
            end
        end)
        f.InputChanged:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch then di = i end
        end)
        UIS.InputChanged:Connect(function(i)
            if i == di and dn then
                if uiLocked then dn = false; return end
                if _isDraggingButton then return end
                local nX = sp.X.Offset + (i.Position.X - ds.X); local nY = sp.Y.Offset + (i.Position.Y - ds.Y)
                f.Position = UDim2.new(sp.X.Scale, nX, sp.Y.Scale, nY)
            end
        end)
    end
    function setupMovementAndIndicators(char)
        if _G.Lust.Connections.movement then _G.Lust.Connections.movement:Disconnect(); _G.Lust.Connections.movement = nil end
        if _G.Lust.Connections.stepped then _G.Lust.Connections.stepped:Disconnect(); _G.Lust.Connections.stepped = nil end
    
        _G.Lust.Connections.stepped = RunService.Stepped:Connect(function()
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP and p.Character then
                    for _, part in ipairs(p.Character:GetChildren()) do
                        if part:IsA("BasePart") then part.CanCollide = false end
                    end
                end
            end
        end)
    
        _G.Lust.Connections.movement = RunService.RenderStepped:Connect(function()
            local char2 = LP.Character
            if not char2 then return end
    
            local hum = char2:FindFirstChildOfClass("Humanoid")
            local hrp = char2:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end
    
            if not autoBatEnabled and not bypassToggled and not autoLeftEnabled and not autoRightEnabled then
                local md = hum.MoveDirection
                local spd = getActiveMoveSpeed()
                local dir = nil
    
                if md.Magnitude > 0.001 then
                    lastMoveDir = md
                    dir = md
                elseif lastMoveDir.Magnitude > 0 then
                    for key in pairs(MOVE_KEYS) do
                        if UIS:IsKeyDown(key) then
                            dir = lastMoveDir
                            break
                        end
                    end
                elseif not antiRagdollEnabled then
                    lastMoveDir = Vector3.zero
                end
    
                if dir and dir.Magnitude > 0.05 then
                    local unit = dir.Unit
                    local currentVelocity = hrp.AssemblyLinearVelocity
                    hrp.AssemblyLinearVelocity = Vector3.new(
                        unit.X * spd,
                        currentVelocity.Y,
                        unit.Z * spd
                    )
                else
                    local currentVelocity = hrp.AssemblyLinearVelocity
                    hrp.AssemblyLinearVelocity = Vector3.new(0, currentVelocity.Y, 0)
                end
    
                _speedLVClear(hrp)
            end
    
            if speedLabel then
                local v = hrp.AssemblyLinearVelocity or hrp.Velocity
                local flatSpeed = math.sqrt(v.X * v.X + v.Z * v.Z)
                speedLabel.Text = "Speed: " .. string.format("%.1f", flatSpeed)
            end
        end)
    
        setupSpeedIndicator(char)
        startEnemySpeed()
    end
    function toggleHideButtons(state)
        if state == nil then hideButtonsEnabled = not hideButtonsEnabled else hideButtonsEnabled = state end
        local visible = not hideButtonsEnabled
    
        if MobilePanel then
            local floatingPanel = MobilePanel:FindFirstChild("FloatingPanel")
            if floatingPanel then
                local buttonsContainer = floatingPanel:FindFirstChild("ButtonsContainer")
                if buttonsContainer then
                    buttonsContainer.Visible = visible
                end
            end
        end
    
        if instaResetFloatingButton then
            local frame = instaResetFloatingButton:FindFirstChild("Frame")
            if frame then frame.Visible = visible end
        end
        if bypassFloatingButton then
            local frame = bypassFloatingButton:FindFirstChild("Frame")
            if frame then frame.Visible = visible end
        end
    
        if setHideButtonsVisual then setHideButtonsVisual(hideButtonsEnabled) end
    end
    
    function toggleLockUI(state)
        if state == nil then uiLocked = not uiLocked else uiLocked = state end
        if setLockUIVisual then setLockUIVisual(uiLocked) end
    end
    function disableAllAimbots()
        if autoBatEnabled then disableAutoBat() end
        if bypassToggled then toggleBypass(false) end
    end
    function stopAllBackgroundTasks()
        _G.Lust.StopAll()
        for _, t in ipairs(dropConnections) do
            if type(t) == "thread" then pcall(task.cancel, t)
            elseif type(t) == "RBXScriptConnection" then pcall(t.Disconnect, t) end
        end
        dropConnections = {}; dropActive = false; alPhase = 1; arPhase = 1
        lastDropTime = 0; medusaDebounce = false; medusaLastUsed = 0
    end
    
