    function updateProgressBarVisibility() if pbFrame then pbFrame.Visible = CONFIG.AUTO_STEAL_ENABLED end end
    function applyShimmerToText(obj, speed)
        speed = speed or 0.8
        local grad = Instance.new("UIGradient", obj)
        grad.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, Color3.fromRGB(55, 20, 75)),
            ColorSequenceKeypoint.new(0.3, Color3.fromRGB(170, 70, 255)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(170, 70, 255)),
            ColorSequenceKeypoint.new(0.7, Color3.fromRGB(170, 70, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(55, 20, 75))})
        grad.Rotation = 45; grad.Offset = Vector2.new(0,0)
        task.spawn(function()
            local t = 0
            while grad and grad.Parent do
                t = t + 0.02; grad.Offset = Vector2.new(math.sin(t * speed) * 0.4, 0); task.wait(0.04)
            end
        end)
        return grad
    end
    
    -- ============================================================
    -- BUTTON RED OUTLINE ONLY
    -- ============================================================
    local function addButtonRedOutline(target)
        if not target or not target:IsA("GuiObject") then return end
        for _, c in ipairs(target:GetChildren()) do
            if c:IsA("UIStroke") and c.Name == "ButtonRedOutline" then
                c:Destroy()
            end
        end
        local stroke = Instance.new("UIStroke")
        stroke.Name = "ButtonRedOutline"
        stroke.Thickness = 1.2
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Color = Color3.fromRGB(170, 70, 255)
        stroke.Transparency = 0
        stroke.LineJoinMode = Enum.LineJoinMode.Round
        stroke.Parent = target
    end
    
    -- ============================================================
    -- ★★★ ROTATING BLACK & WHITE OUTLINE SYSTEM (ANIMATED) ★★★
    -- Shared loop — lahat ng button borders ay gumagalaw (rotating gradient).
    -- ============================================================
    local _bwStrokes = {}
    _G._bwLoopStarted = false
    
    local function makeRotatingBW(target, thickness, speed)
        if not target or not target:IsA("GuiObject") then return end
    
        thickness = thickness or 2.5
        speed = speed or 3
    
        -- remove previous rotating BW
        for _, c in ipairs(target:GetChildren()) do
            if c:IsA("UIStroke") and c.Name == "RotatingBWBorder" then
                c:Destroy()
            end
        end
    
        local stroke = Instance.new("UIStroke")
        stroke.Name = "RotatingBWBorder"
        stroke.Thickness = thickness
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Color = Color3.fromRGB(255, 255, 255)
        stroke.Transparency = 0
        stroke.LineJoinMode = Enum.LineJoinMode.Round
        stroke.Parent = target
    
        local grad = Instance.new("UIGradient")
        grad.Name = "RotatingBWGradient"
        -- BLACK → RED → BLACK moving band (animasyon ng border)
        grad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0.00, Color3.fromRGB(0, 0, 0)),
            ColorSequenceKeypoint.new(0.22, Color3.fromRGB(0, 0, 0)),
            ColorSequenceKeypoint.new(0.42, Color3.fromRGB(170, 70, 255)),
            ColorSequenceKeypoint.new(0.50, Color3.fromRGB(200, 110, 255)),
            ColorSequenceKeypoint.new(0.58, Color3.fromRGB(170, 70, 255)),
            ColorSequenceKeypoint.new(0.78, Color3.fromRGB(0, 0, 0)),
            ColorSequenceKeypoint.new(1.00, Color3.fromRGB(0, 0, 0))
        })
        grad.Rotation = 0
        grad.Parent = stroke
    
        table.insert(_bwStrokes, {stroke = stroke, grad = grad, speed = speed})
    
        if not _G._bwLoopStarted then
            _G._bwLoopStarted = true
            task.spawn(function()
                while true do
                    for i = #_bwStrokes, 1, -1 do
                        local e = _bwStrokes[i]
                        if e.stroke and e.stroke.Parent and e.grad and e.grad.Parent then
                            e.grad.Rotation = (e.grad.Rotation + e.speed) % 360
                        else
                            table.remove(_bwStrokes, i)
                        end
                    end
                    task.wait(0.016)
                end
            end)
        end
        return stroke, grad
    end
    
    -- Apply rotating BW sa LAHAT ng Button + stroked Frame
    -- ★ BINAGO: Ngayon ang mga Button ay may ANIMATED black-red border ★
    local function applyBWToEverything(root, thickness, speed)
        if not root then return end
        thickness = thickness or 2.5
        speed = speed or 3
        for _, d in ipairs(root:GetDescendants()) do
            if (d:IsA("TextButton") or d:IsA("ImageButton")) and not d:GetAttribute("NoGlobalBW") then
                -- ★ ANIMATED BLACK-RED ROTATING BORDER SA MGA BUTTON ★
                pcall(makeRotatingBW, d, 3, 4)
            elseif d:IsA("Frame") then
                local hasStroke = false
                for _, c in ipairs(d:GetChildren()) do
                    if c:IsA("UIStroke") then hasStroke = true; break end
                end
                if hasStroke then pcall(makeRotatingBW, d, thickness, speed) end
            end
        end
    end
    
    function getDefaultButtonPosition(btnName)
        local positions = {TpBat = {0, 0}, DropBR = {86, 0}, AutoLeft = {176, 0},
            AutoBat = {86, 104}, AutoRight = {176, 104},
            TpDown = {86, 208}, Carry = {176, 208},
            Lagger1 = {86, 312}, Lagger2 = {176, 312}}
        local pos = positions[btnName] or {0, 0}
        return pos[1], pos[2]
    end
    
