        -- GUI OPEN/CLOSE: Fade + Scale/Pop-In animation.
        -- Keep the original intro/background implementation untouched.
        local guiOpenTween
        local guiCloseTween
        local tabBar, tabContent
        local GUI_POP_SCALE = 0.78
        local GUI_ANIM_TIME = 0.28
    
        -- GUI IDLE TRANSPARENCY:
        -- Kapag walang interaction sa menu, kusang nagfa-fade ang buong main GUI.
        -- Kapag tinap/tina-click ulit ang menu, babalik agad sa normal na visibility.
        local GUI_IDLE_DELAY = 1.20
        local GUI_IDLE_FADE = 0.55
        local GUI_IDLE_TWEEN = 0.22
        local guiIdleToken = 0
        local guiIdleFading = false
        local guiNormalTransparency = {}
        local guiFadeTweens = {}
        local guiIdleConnections = {}
    
        local function cancelGuiIdleTweens()
            for _, tween in ipairs(guiFadeTweens) do
                pcall(function() tween:Cancel() end)
            end
            table.clear(guiFadeTweens)
        end
    
        local function rememberGuiTransparency(obj)
            if not obj then return end
            local data = guiNormalTransparency[obj]
            if not data then
                data = {}
                guiNormalTransparency[obj] = data
            end
            pcall(function()
                if obj:IsA("GuiObject") and data.BackgroundTransparency == nil then
                    data.BackgroundTransparency = obj.BackgroundTransparency
                end
                if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                    if data.TextTransparency == nil then data.TextTransparency = obj.TextTransparency end
                    if data.TextStrokeTransparency == nil then data.TextStrokeTransparency = obj.TextStrokeTransparency end
                end
                if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                    if data.ImageTransparency == nil then data.ImageTransparency = obj.ImageTransparency end
                end
                if obj:IsA("UIStroke") and data.Transparency == nil then
                    data.Transparency = obj.Transparency
                end
            end)
        end
    
        local function getGuiTransparencyObjects()
            local list = {}
            if main then
                table.insert(list, main)
                for _, obj in ipairs(main:GetDescendants()) do
                    -- NEVER fade the selected background image.
                    -- It must stay visible through close -> open and idle fade.
                    if obj ~= bgImageRef then
                        table.insert(list, obj)
                    end
                end
            end
            return list
        end
    
        local function restoreBackgroundImage()
            if not main or not bgImageRef then return end
            local asset = BackgroundImages[currentBgIndex]
            if currentBgIndex == 1 or not asset then
                bgImageRef.Image = ""
                bgImageRef.Visible = false
                main.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
                main.BackgroundTransparency = 0
            else
                bgImageRef.Image = asset
                bgImageRef.Visible = true
                bgImageRef.ImageTransparency = 0
                main.BackgroundTransparency = 1
            end
        end
    
        local function tweenGuiTransparency(faded)
            cancelGuiIdleTweens()
            for _, obj in ipairs(getGuiTransparencyObjects()) do
                rememberGuiTransparency(obj)
                local data = guiNormalTransparency[obj]
                if not data then continue end
                local goal = {}
                if obj:IsA("GuiObject") and data.BackgroundTransparency ~= nil then
                    goal.BackgroundTransparency = faded and math.clamp(data.BackgroundTransparency + GUI_IDLE_FADE, 0, 0.96) or data.BackgroundTransparency
                end
                if (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then
                    if data.TextTransparency ~= nil then
                        goal.TextTransparency = faded and math.clamp(data.TextTransparency + GUI_IDLE_FADE, 0, 0.96) or data.TextTransparency
                    end
                    if data.TextStrokeTransparency ~= nil then
                        goal.TextStrokeTransparency = faded and math.clamp(data.TextStrokeTransparency + GUI_IDLE_FADE, 0, 0.96) or data.TextStrokeTransparency
                    end
                end
                if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                    if data.ImageTransparency ~= nil then
                        goal.ImageTransparency = faded and math.clamp(data.ImageTransparency + GUI_IDLE_FADE, 0, 0.96) or data.ImageTransparency
                    end
                end
                if obj:IsA("UIStroke") and data.Transparency ~= nil then
                    goal.Transparency = faded and math.clamp(data.Transparency + GUI_IDLE_FADE, 0, 0.96) or data.Transparency
                end
                if next(goal) then
                    local tween = TS:Create(obj, TweenInfo.new(GUI_IDLE_TWEEN, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), goal)
                    table.insert(guiFadeTweens, tween)
                    tween:Play()
                end
            end
            guiIdleFading = faded
        end
    
        local function showGuiFromIdle()
            if not main or not main.Visible then return end
            guiIdleToken += 1
            -- IMPORTANT: do not recreate dozens of tweens on every touch/swipe.
            -- Only restore the menu when it is actually faded.
            if guiIdleFading then
                tweenGuiTransparency(false)
            end
        end
    
        local function scheduleGuiIdleFade()
            guiIdleToken += 1
            local myToken = guiIdleToken
            task.delay(GUI_IDLE_DELAY, function()
                if myToken ~= guiIdleToken then return end
                if main and main.Visible then
                    tweenGuiTransparency(true)
                end
            end)
        end
    
        local function bindGuiIdleInput(obj)
            if not obj or not obj:IsA("GuiObject") then return end
            if obj:GetAttribute("GuiIdleTransparencyBound") then return end
            obj:SetAttribute("GuiIdleTransparencyBound", true)
            rememberGuiTransparency(obj)
            table.insert(guiIdleConnections, obj.InputBegan:Connect(function(input)
                -- Only actual click/tap wakes the GUI. MouseMovement/MouseEnter
                -- are intentionally ignored because they fire repeatedly while
                -- dragging/swiping a ScrollingFrame and can cause frame drops.
                if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                    showGuiFromIdle()
                    scheduleGuiIdleFade()
                end
            end))
        end
    
        local function setupGuiIdleTransparency()
            if not main then return end
            bindGuiIdleInput(main)
            for _, obj in ipairs(main:GetDescendants()) do
                bindGuiIdleInput(obj)
                rememberGuiTransparency(obj)
            end
            table.insert(guiIdleConnections, main.DescendantAdded:Connect(function(obj)
                if obj:IsA("GuiObject") then bindGuiIdleInput(obj) end
                rememberGuiTransparency(obj)
            end))
            scheduleGuiIdleFade()
        end
    
        local function cancelGuiAnimation()
            if guiOpenTween then
                pcall(function() guiOpenTween:Cancel() end)
                guiOpenTween = nil
            end
            if guiCloseTween then
                pcall(function() guiCloseTween:Cancel() end)
                guiCloseTween = nil
            end
        end
    
        local function animateShow()
            cancelGuiAnimation()
    
            miniBtn.Visible = true
            miniBtn.ZIndex = 1000
            main.Visible = true
            main.Size = UDim2.new(0, GUI_W, 0, GUI_H)
    
            -- Kapag binuksan, ibalik muna ang original background image.
            -- Hindi ito dapat nawawala kahit na nag-fade o nagsara ang GUI.
            restoreBackgroundImage()
            tweenGuiTransparency(false)
    
            if not savedMainGuiPos then
                main.Position = UDim2.new(0.5, -GUI_W/2, 0.5, -GUI_H/2)
            end
    
            -- Animate only UIScale so the existing background image and intro
            -- are preserved exactly as they are in the source.
            mainUIScale.Scale = (uiScaleValue / 100) * GUI_POP_SCALE
            guiOpenTween = TS:Create(
                mainUIScale,
                TweenInfo.new(GUI_ANIM_TIME, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                {Scale = uiScaleValue / 100}
            )
            guiOpenTween:Play()
    
            -- Extra tab/menu squish effect: the tab rail and content start
            -- slightly compressed, then settle into their normal size.
            local tabAnimScale = tabBar and (tabBar:FindFirstChild("TabsOpenScale") or Instance.new("UIScale"))
            if tabAnimScale then
                tabAnimScale.Name = "TabsOpenScale"
                tabAnimScale.Scale = 0.90
                tabAnimScale.Parent = tabBar
            end
            local contentAnimScale = tabContent and (tabContent:FindFirstChild("TabsContentOpenScale") or Instance.new("UIScale"))
            if contentAnimScale then
                contentAnimScale.Name = "TabsContentOpenScale"
                contentAnimScale.Scale = 0.96
                contentAnimScale.Parent = tabContent
            end
            if tabAnimScale then
                TS:Create(tabAnimScale, TweenInfo.new(0.30, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
            end
            if contentAnimScale then
                TS:Create(contentAnimScale, TweenInfo.new(0.26, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = 1}):Play()
            end
    
            guiOpenTween.Completed:Once(function()
                if main and main.Visible then
                    mainUIScale.Scale = uiScaleValue / 100
                    if tabAnimScale then tabAnimScale.Scale = 1 end
                    if contentAnimScale then contentAnimScale.Scale = 1 end
                end
                guiOpenTween = nil
            end)
    
            scheduleGuiIdleFade()
            pcall(saveAllSettings)
        end
    
        local function animateHide()
            if not main.Visible then return end
            cancelGuiAnimation()
    
            guiCloseTween = TS:Create(
                mainUIScale,
                TweenInfo.new(GUI_ANIM_TIME, Enum.EasingStyle.Back, Enum.EasingDirection.In),
                {Scale = (uiScaleValue / 100) * GUI_POP_SCALE}
            )
            guiCloseTween:Play()
    
            local tabAnimScale = tabBar and tabBar:FindFirstChild("TabsOpenScale")
            local contentAnimScale = tabContent and tabContent:FindFirstChild("TabsContentOpenScale")
            if tabAnimScale then
                TS:Create(tabAnimScale, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.92}):Play()
            end
            if contentAnimScale then
                TS:Create(contentAnimScale, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.96}):Play()
            end
    
            guiCloseTween.Completed:Once(function()
                if main then
                    main.Visible = false
