                    mainUIScale.Scale = uiScaleValue / 100
                    local tabAnimScale = tabBar and tabBar:FindFirstChild("TabsOpenScale")
                    local contentAnimScale = tabContent and tabContent:FindFirstChild("TabsContentOpenScale")
                    if tabAnimScale then tabAnimScale.Scale = 0.90 end
                    if contentAnimScale then contentAnimScale.Scale = 0.96 end
                end
                miniBtn.Visible = true
                guiCloseTween = nil
            end)
        end
    
