            Instance.new("UICorner", holdBtn).CornerRadius = UDim.new(0, 9)
    
            local function updateJumpModeButtons(mode)
                local manual = mode == "Manual"
                local activeBg = Color3.fromRGB(170, 70, 255)
                local inactiveBg = Color3.fromRGB(0, 0, 0)
                manualBtn.BackgroundColor3 = manual and activeBg or inactiveBg
                manualBtn.TextColor3 = WHITE
                holdBtn.BackgroundColor3 = (not manual) and activeBg or inactiveBg
                holdBtn.TextColor3 = WHITE
    
                local ms = manualBtn:FindFirstChild("JumpModeStroke")
                local hs = holdBtn:FindFirstChild("JumpModeStroke")
                if not ms then
                    ms = Instance.new("UIStroke", manualBtn); ms.Name = "JumpModeStroke"; ms.Thickness = 1.1
                end
                if not hs then
                    hs = Instance.new("UIStroke", holdBtn); hs.Name = "JumpModeStroke"; hs.Thickness = 1.1
                end
                ms.Color = manual and Color3.fromRGB(170, 70, 255) or Color3.fromRGB(45, 45, 45)
                hs.Color = (not manual) and Color3.fromRGB(170, 70, 255) or Color3.fromRGB(45, 45, 45)
                ms.Transparency = manual and 0 or 0.45
                hs.Transparency = (not manual) and 0 or 0.45
            end
    
            setJumpModeVisual = updateJumpModeButtons
            updateJumpModeButtons(jumpMode)
    
            manualBtn.Activated:Connect(function()
                setJumpMode("Manual")
