                st.Color = (dropMode == mode) and WHITE or ROW_BORDER
                st.Thickness = (dropMode == mode) and 1.8 or 1.1
                st.Transparency = (dropMode == mode) and 0.05 or 0.35
    
                b.Activated:Connect(function()
