            local function changeBackgroundFromVisuals(step)
                local count = #BackgroundImages
                if count <= 0 then return end
                currentBgIndex = ((currentBgIndex - 1 + step) % count) + 1
                applyBackgroundImage(currentBgIndex)
                for i, btn in ipairs(bgButtons) do
                    local st = btn:FindFirstChildOfClass("UIStroke")
                    if st then
                        local selected = (i == currentBgIndex)
                        st.Color = selected and Color3.fromRGB(170, 70, 255) or Color3.fromRGB(140, 0, 0)
                        st.Thickness = selected and 2.5 or 1
                        st.Transparency = selected and 0.1 or 0.6
                    end
                end
            end
    
            leftArrow.Activated:Connect(function()
                changeBackgroundFromVisuals(-1)
            end)
            rightArrow.Activated:Connect(function()
                changeBackgroundFromVisuals(1)
            end)
    
            local function updateBgGallery()
                for i, btn in ipairs(bgButtons) do
                    local st = btn:FindFirstChildOfClass("UIStroke")
                    if st then
                        local selected = (i == currentBgIndex)
                        st.Color = selected and Color3.fromRGB(170, 70, 255) or Color3.fromRGB(140, 0, 0)
                        st.Thickness = selected and 2.5 or 1
