                if not asset then
                    local noneLabel = Instance.new("TextLabel", btn)
                    noneLabel.Size = UDim2.new(1, 0, 1, 0)
                    noneLabel.BackgroundTransparency = 1
                    noneLabel.Text = "NONE"
                    noneLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
