                card.Activated:Connect(function()
                    setSkyTheme(themeName)
                    saveAllSettings()
                    for _, ref in ipairs(skyCardRefs) do
                        if ref.card and ref.card.Parent then ref.setSelected(ref.card, ref.name == currentSkyTheme) end
                    end
                    -- Automatically close after selecting a Sky Theme.
                    if closeSkyThemePreview then
                        closeSkyThemePreview()
                    end
                end)
    
                table.insert(skyCardRefs, {name = themeName, card = card, setSelected = setSkyCardSelected})
            end
    
