            local function makePreview(card, packName)
                local viewport = Instance.new("ViewportFrame", card)
                viewport.Name = "AvatarPreview"
                viewport.Size = UDim2.new(1, 0, 1, -22)
                viewport.BackgroundColor3 = Color3.fromRGB(8, 8, 8)
                viewport.BorderSizePixel = 0
                viewport.ZIndex = 503
                viewport.Ambient = Color3.fromRGB(170, 70, 255)
                viewport.LightColor = Color3.fromRGB(170, 70, 255)
                viewport.LightDirection = Vector3.new(-1, -1, -1)
                Instance.new("UICorner", viewport).CornerRadius = UDim.new(0, 8)
    
                local world = Instance.new("WorldModel")
                world.Parent = viewport
                local char = LP.Character
                if not char then return end
                local oldArchivable = char.Archivable
                char.Archivable = true
                local ok, clone = pcall(function() return char:Clone() end)
                char.Archivable = oldArchivable
                if not ok or not clone then return end
    
                for _, d in ipairs(clone:GetDescendants()) do
                    if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("ModuleScript") then
                        pcall(function() d:Destroy() end)
                    elseif d:IsA("BasePart") then
                        d.Anchored = true; d.CanCollide = false; d.CanTouch = false; d.CanQuery = false
                    end
                end
                if packName ~= "Off" and BLEED_PACKS[packName] then
                    local cfg = BLEED_PACKS[packName]
                    for _, d in ipairs(clone:GetChildren()) do
                        if d:IsA("Shirt") or d:IsA("Pants") or d:IsA("Accessory") or d:IsA("Hat") then d:Destroy() end
                    end
                    if cfg.shirt then local sh=Instance.new("Shirt"); sh.ShirtTemplate=cfg.shirt; sh.Parent=clone end
                    if cfg.pants then local pa=Instance.new("Pants"); pa.PantsTemplate=cfg.pants; pa.Parent=clone end
                    local head=clone:FindFirstChild("Head")
                    if head and cfg.headMesh then
                        if head:IsA("MeshPart") then
                            pcall(function() head.MeshId=cfg.headMesh; if cfg.headTexture then head.TextureID=cfg.headTexture end end)
                        else
                            local sm=head:FindFirstChildWhichIsA("SpecialMesh") or Instance.new("SpecialMesh")
                            sm.MeshType=Enum.MeshType.FileMesh; sm.MeshId=cfg.headMesh; sm.TextureId=cfg.headTexture or ""; sm.Parent=head
                        end
                    end
                    -- USE THE ACTUAL AVATAR SOURCE ACCESSORY FROM BLEED_PACKS.
                    if cfg.accessory and head then
                        local objs=nil
                        local ok,res=pcall(function() return game:GetObjects("rbxassetid://"..tostring(cfg.accessory)) end)
                        if ok and typeof(res)=="table" and #res>0 then objs=res else
                            ok,res=pcall(function() return game:GetService("InsertService"):LoadAsset(cfg.accessory) end)
                            if ok and res then objs={res} end
                        end
                        if objs then
                            local srcAcc
                            for _,o in ipairs(objs) do
                                if o:IsA("Accessory") then srcAcc=o; break end
                                local a=o:FindFirstChildWhichIsA("Accessory",true); if a then srcAcc=a; break end
                            end
                            if srcAcc then
                                local acc=srcAcc:Clone()
                                acc.Parent=clone
                                local hum=clone:FindFirstChildOfClass("Humanoid")
                                if hum then
                                    pcall(function() hum:AddAccessory(acc) end)
                                else
                                    local handle=acc:FindFirstChild("Handle")
                                    if handle then
                                        handle.Anchored=true; handle.CanCollide=false; handle.CanTouch=false; handle.CanQuery=false
                                        handle.CFrame=head.CFrame*CFrame.new(cfg.offset or Vector3.zero)
                                    end
                                end
                            end
                            for _,o in ipairs(objs) do pcall(function() o:Destroy() end) end
                        end
                    end
                    -- USE THE SOURCE KORBLOX SETTING TOO, so Outfit 3 matches the source avatar.
                    if cfg.korblox and cfg.korblox ~= "none" then
                        local ids={left=139607673,right=139607718}
                        local targets={left="LeftUpperLeg",right="RightUpperLeg"}
                        local target=clone:FindFirstChild(targets[cfg.korblox])
                        if target and ids[cfg.korblox] then
                            local ok,res=pcall(function() return game:GetObjects("rbxassetid://"..ids[cfg.korblox]) end)
                            if ok and res and #res>0 then
                                local asset=res[1]
                                local part=asset:IsA("BasePart") and asset or asset:FindFirstChildWhichIsA("BasePart",true)
                                if part then
                                    local k=part:Clone(); k.Name="PreviewKorblox"; k.Anchored=true; k.CanCollide=false; k.CanTouch=false; k.CanQuery=false; k.CFrame=target.CFrame; k.Parent=clone
                                    target.Transparency=1
                                    local low=clone:FindFirstChild(cfg.korblox=="left" and "LeftLowerLeg" or "RightLowerLeg"); if low then low.Transparency=1 end
                                    local foot=clone:FindFirstChild(cfg.korblox=="left" and "LeftFoot" or "RightFoot"); if foot then foot.Transparency=1 end
                                end
                                for _,o in ipairs(res) do pcall(function() o:Destroy() end) end
                            end
                        end
                    end
                end
                clone.Parent = world
                for _, joint in ipairs(clone:GetDescendants()) do
                    if joint:IsA("Motor6D") and string.lower(joint.Name):find("shoulder") then pcall(function() joint.Transform=CFrame.Angles(math.rad(65),0,0) end) end
                end
                pcall(function() clone:PivotTo(CFrame.new()) end)
                local cam=Instance.new("Camera"); cam.Parent=viewport; viewport.CurrentCamera=cam
                local boxCFrame, boxSize=clone:GetBoundingBox(); local focus=boxCFrame.Position+Vector3.new(0,boxSize.Y*0.02,0); local distance=math.max(boxSize.Y*1.02,5)
                cam.CFrame=CFrame.lookAt(focus+Vector3.new(0,0.05,distance),focus)
                local previewBase=clone:GetPivot(); local previewStart=tick(); local previewConn
                previewConn=RunService.RenderStepped:Connect(function()
                    if not viewport.Parent or not clone.Parent then if previewConn then previewConn:Disconnect() end; return end
                    local t=tick()-previewStart; clone:PivotTo(previewBase*CFrame.new(0,math.sin(t*2.2)*0.035,0)*CFrame.Angles(0,t*math.rad(24),0))
                end)
            end
    
