                local world = Instance.new("WorldModel", viewport)
                local template = sourceGetExactTemplate(skinName)
                local model
                if template then
                    local clone = template:Clone()
                    model = sourceContainerToModel(clone, world)
                end
                if not model then
                    local fakeTool = Instance.new("Tool")
                    fakeTool.Name = "Bat"
                    local fakeHandle = Instance.new("Part")
                    fakeHandle.Name = "Handle"
                    fakeHandle.Size = Vector3.new(1, 1, 1)
                    fakeHandle.Transparency = 1
                    fakeHandle.Anchored = true
                    fakeHandle.Parent = fakeTool
                    fakeTool.Parent = world
                    model = sourceBuildProxyModel(fakeTool, skinName, world)
                    fakeTool:Destroy()
                end
                for _, inst in ipairs(model:GetDescendants()) do
                    if inst:IsA("BasePart") then
                        inst.Anchored = true; inst.CanCollide = false; inst.CanTouch = false; inst.CanQuery = false
                    elseif inst:IsA("Script") or inst:IsA("LocalScript") or inst:IsA("ModuleScript") then
