                viewport.CurrentCamera = cam
                local box = model:GetBoundingBox()
                local focus = box.Position
                local dist = math.max(math.max(size.X, size.Y, size.Z) * 1.7, 4.5)
                cam.CFrame = CFrame.lookAt(focus + Vector3.new(0, 0.05, dist), focus)
                local base = model:GetPivot()
