            local function setFontCardSelected(card, selected)
                local st = card:FindFirstChild("SelectionStroke")
                if st then
                    st.Color = selected and WHITE or ROW_BORDER
                    st.Thickness = selected and 2.5 or 1
                    st.Transparency = selected and 0 or 0.35
                end
            end
    
            local function makeFontCard(entry, index)
                local card = Instance.new("TextButton", cardsScroll)
                card.Name = "Font_" .. entry.name
                card.Text = ""
                card.AutoButtonColor = false
                card.BackgroundColor3 = Color3.fromRGB(8, 8, 8)
                card.BackgroundTransparency = 0.05
                card.BorderSizePixel = 0
                card.LayoutOrder = index
                card.ZIndex = 623
                card.Selectable = false
                card:SetAttribute("NoGlobalBW", true)
                Instance.new("UICorner", card).CornerRadius = UDim.new(0, 12)
    
                local st = Instance.new("UIStroke", card)
                st.Name = "SelectionStroke"
                st.Color = ROW_BORDER
                st.Thickness = 1
                st.Transparency = 0.35
    
                local sample = Instance.new("TextLabel", card)
                sample.Name = "FontSample"
                sample.Size = UDim2.new(1, -10, 0, 65)
                sample.Position = UDim2.new(0, 5, 0, 4)
                sample.BackgroundTransparency = 1
                sample.Text = "Aa"
                sample.TextColor3 = WHITE
                sample.TextScaled = true
                sample.TextXAlignment = Enum.TextXAlignment.Center
                sample.TextYAlignment = Enum.TextYAlignment.Center
                sample.ZIndex = 624
                sample:SetAttribute("FontPreviewCard", true)
                pcall(function()
                    local ok, face = pcall(Font.new, entry.path)
                    if ok and face then sample.FontFace = face end
                end)
    
                local label = Instance.new("TextLabel", card)
                label.Name = "FontName"
                label.Size = UDim2.new(1, -8, 0, 35)
                label.Position = UDim2.new(0, 4, 1, -39)
                label.BackgroundTransparency = 1
                label.Text = entry.name
                label.TextColor3 = WHITE
                label.Font = Enum.Font.GothamBold
                label.TextSize = 9
                label.TextWrapped = true
                label.TextXAlignment = Enum.TextXAlignment.Center
                label.ZIndex = 624
    
                card.Activated:Connect(function()
                    fontStyleIndex = index
                    if fontStyleLabel then
                        fontStyleLabel.Text = string.upper(entry.name)
                    end
                    applyFontStyle()
                    saveAllSettings()
                    for _, ref in ipairs(fontCardRefs) do
                        if ref.card and ref.card.Parent then
                            ref.setSelected(ref.card, ref.index == fontStyleIndex)
                        end
                    end
                    local tw = TS:Create(modalScale, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.92})
                    tw:Play()
                    task.delay(0.14, function()
                        if overlay and overlay.Parent then
                            overlay.Visible = false
                            modalScale.Scale = 0.82
                        end
                    end)
                end)
    
                table.insert(fontCardRefs, {index = index, card = card, setSelected = setFontCardSelected})
            end
    
            for i, entry in ipairs(FONT_STYLE_LIST) do
                makeFontCard(entry, i)
            end
    
            local modalScale = Instance.new("UIScale")
            modalScale.Name = "FontStylePopScale"
            modalScale.Scale = 0.82
            modalScale.Parent = modal
    
            for _, ref in ipairs(fontCardRefs) do
                ref.setSelected(ref.card, ref.index == fontStyleIndex)
            end
    
            local closing = false
            local function closeFontPreview()
                if not overlay.Visible or closing then return end
                closing = true
                local tw = TS:Create(modalScale, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.82})
                tw:Play()
                tw.Completed:Connect(function()
                    overlay.Visible = false
                    modalScale.Scale = 0.82
                    closing = false
                end)
            end
    
            close.Activated:Connect(closeFontPreview)
            close.MouseButton1Click:Connect(closeFontPreview)
            close.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                    closeFontPreview()
                end
            end)
    
            pickBtn.Activated:Connect(function()
                if closing then return end
                overlay.Visible = true
                overlay.BackgroundTransparency = 0.42
                modalScale.Scale = 0.82
                for _, ref in ipairs(fontCardRefs) do
                    if ref.card and ref.card.Parent then
                        ref.setSelected(ref.card, ref.index == fontStyleIndex)
                    end
                end
                TS:Create(modalScale, TweenInfo.new(0.24, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
            end)
        end
