            }
    
            local buttons = {}
            local function setAnimButton(btn, selected)
                btn.BackgroundColor3 = selected and Color3.fromRGB(170, 70, 255) or Color3.fromRGB(245, 250, 255)
                btn.BackgroundTransparency = selected and 0 or 0.02
                btn.TextColor3 = selected and WHITE or Color3.fromRGB(90, 45, 120)
                local st = btn:FindFirstChild("AnimSelectionStroke")
                if st then
                    st.Color = selected and Color3.fromRGB(170, 70, 255) or Color3.fromRGB(210, 180, 255)
                    st.Thickness = selected and 1.4 or 0.8
                    st.Transparency = selected and 0.05 or 0.35
                end
            end
    
            local function refreshAnimButtons()
                if animSelectorLabel then
                    animSelectorLabel.Text = string.upper(currentAnimPack or "OFF")
                end
                for _, ref in ipairs(buttons) do
                    setAnimButton(ref.button, ref.packName == currentAnimPack)
                end
            end
    
            local layout = Instance.new("UIListLayout", selector)
            layout.FillDirection = Enum.FillDirection.Horizontal
            layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
            layout.VerticalAlignment = Enum.VerticalAlignment.Center
            layout.Padding = UDim.new(0, 4)
            layout.SortOrder = Enum.SortOrder.LayoutOrder
    
            local pad = Instance.new("UIPadding", selector)
            pad.PaddingLeft = UDim.new(0, 5)
            pad.PaddingRight = UDim.new(0, 5)
    
            for i, entry in ipairs(list) do
                local label, packName = entry[1], entry[2]
                local btn = Instance.new("TextButton", selector)
                btn.Name = "AnimStyle_" .. label:gsub("%s+", "_")
                btn.Size = UDim2.new(0, label == "NONE" and 54 or 38, 0, 26)
                btn.BackgroundColor3 = Color3.fromRGB(245, 250, 255)
                btn.BackgroundTransparency = 0.02
                btn.BorderSizePixel = 0
                btn.Text = label
                btn.TextColor3 = Color3.fromRGB(90, 45, 120)
                btn.Font = Enum.Font.GothamBlack
                btn.TextSize = label == "NONE" and 8 or 10
                btn.AutoButtonColor = false
                btn.LayoutOrder = i
                btn.ZIndex = 10
                Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 10)
    
                local st = Instance.new("UIStroke", btn)
                st.Name = "AnimSelectionStroke"
                st.Color = Color3.fromRGB(210, 180, 255)
                st.Thickness = 0.8
                st.Transparency = 0.35
    
                btn.Activated:Connect(function()
                    if packName == "Off" then
                        stopAnimPack()
                    else
                        startAnimPack(packName)
                    end
                    saveAllSettings()
                    refreshAnimButtons()
    
                    -- Small press flash, matching the reference selector behavior.
                    btn.BackgroundColor3 = Color3.fromRGB(200, 150, 255)
                    TS:Create(btn, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        BackgroundColor3 = (packName == currentAnimPack)
                            and Color3.fromRGB(170, 70, 255)
                            or Color3.fromRGB(245, 250, 255)
                    }):Play()
                end)
    
                table.insert(buttons, {button = btn, packName = packName})
            end
    
            refreshAnimButtons()
        end
